public async Task AppendAsync(
    string streamId,
    IEvent @event,
    long expectedVersion,
    CancellationToken ct)
{
    var sql = @"
        INSERT INTO Events (StreamId, GlobalPosition, EventType, Payload, Timestamp, CorrelationId)
        VALUES (@StreamId, @GlobalPosition, @EventType, @Payload, @Timestamp, @CorrelationId)
    ";

    var rows = await _db.ExecuteAsync(
        sql,
        new
        {
            StreamId = streamId,
            GlobalPosition = await GetNextPositionAsync(),
            EventType = @event.GetType().Name,
            Payload = JsonSerializer.Serialize(@event),
            Timestamp = DateTime.UtcNow,
            CorrelationId = @event.CorrelationId
        },
        ct);
}

async function readStream(streamId, fromPosition = 0) {
  const result = await db.query(
    `SELECT * FROM events WHERE stream_id = $1 AND global_position >= $2 ORDER BY global_position ASC`,
    [streamId, fromPosition]
  );
  return result.rows.map(row => ({
    position: row.global_position,
    type: row.event_type,
    data: JSON.parse(row.payload),
    timestamp: row.timestamp
  }));
}
